    @Test func compressed() {
        let mismatches = Mismatches("portCompressedI16InVectorCode")
        let aInputs = Inputs.vectors(H.self, seed: 0xE61A_0823_A860_78DE)
        let maskInputs = Inputs.masks(H.Mask.self, seed: 0xE61A_0923_A860_7A91)
        for (a, mask) in everyPair(aInputs, maskInputs) {
            let port = { () -> SIMD<Int16> in
                var a = a
                var mask = mask
                return withUnsafeTemporaryAllocation(of: SIMD<Int16>.self, capacity: 1) { result in
                    unsafe portCompressedI16InVectorCode(
                        result.baseAddress.unsafelyUnwrapped,
                        &a,
                        where: &mask
                    )
                    return unsafe result.baseAddress.unsafelyUnwrapped.move()
                }
            }()
            let reference = { () -> SIMD<Int16> in
                var a = a
                var mask = mask
                return withUnsafeTemporaryAllocation(of: SIMD<Int16>.self, capacity: 1) { result in
                    unsafe highwayCompressedI16InVectorCode(
                        result.baseAddress.unsafelyUnwrapped,
                        &a,
                        where: &mask
                    )
                    return unsafe result.baseAddress.unsafelyUnwrapped.move()
                }
            }()
            let checkedLanes =
                HighwayReference.compressTailIsDeterministicI16() ? H.laneCount : H.trueCount(mask)
            mismatches.check(
                (0..<checkedLanes).map { port.simd[$0] },
                (0..<checkedLanes).map { reference.simd[$0] },
                "a: \(describe(a)), mask: \(describe(mask))"
            )
        }
        mismatches.record()
    }

